#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

FUNCTION_APP="func-twopoint-website-api"
SECRET_NAME="web-push-vapid-private-key"
ADMIN_CONFIG="$(git rev-parse --show-toplevel)/frontend/Admin/config.json"

banner "Web Push: the VAPID key pair of the backend"

# The private key is only in a temporary folder and in a variable of this shell.
KEY_DIR=$(mktemp -d)
trap 'rm -rf "$KEY_DIR"' EXIT

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Azure and find the backend"
say "The wizard uses the Azure CLI for each change. It asks before each change."
if az account show >/dev/null 2>&1; then
  note "You are already signed in as $(az account show --query user.name -o tsv)."
else
  step "A browser window opens for the Azure sign-in."
  pause "Press Enter to start the sign-in."
  az login >/dev/null
fi
APP_RG=$(az functionapp list --query "[?name=='$FUNCTION_APP'].resourceGroup | [0]" -o tsv)
[[ -n "$APP_RG" ]] || { warn "Cannot find $FUNCTION_APP in this subscription."; exit 1; }
app_setting() {
  az functionapp config appsettings list -n "$FUNCTION_APP" -g "$APP_RG" --query "[?name=='$1'].value | [0]" -o tsv
}
VAULT_URI=$(app_setting "Azure__KeyVaultUri")
IDENTITY_CLIENT_ID=$(app_setting "Azure__ManagedIdentityClientId")
[[ -n "$VAULT_URI" ]] || { warn "$FUNCTION_APP has no setting Azure__KeyVaultUri."; exit 1; }
[[ -n "$IDENTITY_CLIENT_ID" ]] || { warn "$FUNCTION_APP has no setting Azure__ManagedIdentityClientId."; exit 1; }
VAULT_NAME=$(printf '%s' "$VAULT_URI" | sed -E 's#https://([^.]+)\..*#\1#')
IDENTITY_PRINCIPAL_ID=$(az identity list --query "[?clientId=='$IDENTITY_CLIENT_ID'].principalId | [0]" -o tsv)
[[ -n "$IDENTITY_PRINCIPAL_ID" ]] || { warn "Cannot find the managed identity $IDENTITY_CLIENT_ID."; exit 1; }
CURRENT_PUBLIC_KEY=$(app_setting "WebPush__PublicKey")
CURRENT_SUBJECT=$(app_setting "WebPush__Subject")
note "Function App: $FUNCTION_APP ($APP_RG)"
note "Key Vault: $VAULT_NAME"
note "Backend identity: $IDENTITY_CLIENT_ID"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Make the key pair"
NEW_PAIR=yes
if [[ -n "$CURRENT_PUBLIC_KEY" ]]; then
  warn "$FUNCTION_APP already has a VAPID public key:"
  note "$CURRENT_PUBLIC_KEY"
  say "A new key pair makes each registered device useless. Each device must turn on notifications again."
  confirm "Make a new key pair in place of the current one?" || NEW_PAIR=no
fi
if [[ "$NEW_PAIR" == yes ]]; then
  b64url() { xxd -r -p | base64 | tr '+/' '-_' | tr -d '=\n'; }
  openssl ecparam -genkey -name prime256v1 -noout -out "$KEY_DIR/vapid.pem"
  KEY_HEX=$(openssl ec -in "$KEY_DIR/vapid.pem" -outform DER 2>/dev/null | xxd -p -c 200)
  # The DER of a P-256 key: 7 bytes of header, the 32-byte private key, ..., 034200, then the 65-byte public key.
  PRIVATE_KEY=$(printf '%s' "${KEY_HEX:14:64}" | b64url)
  PUBLIC_KEY=$(printf '%s' "${KEY_HEX#*034200}" | b64url)
  if [[ "${KEY_HEX:0:14}" != "30770201010420" || ${#PRIVATE_KEY} -ne 43 || ${#PUBLIC_KEY} -ne 87 || "$PUBLIC_KEY" != B* ]]; then
    warn "The key pair does not have the expected shape. The wizard stops and changes nothing."
    exit 1
  fi
  printf '  %s✓ made%s a P-256 key pair\n' "$GREEN" "$RESET"
  note "Public key: $PUBLIC_KEY"
else
  PUBLIC_KEY="$CURRENT_PUBLIC_KEY"
  note "The wizard keeps the current key pair, and only writes its public key to the admin config."
fi
pause

if [[ "$NEW_PAIR" == yes ]]; then

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Put the private key in Key Vault"
say "The backend reads the private key from the secret $SECRET_NAME. The wizard does not show it."
if confirm "Write the private key to $VAULT_NAME as the secret $SECRET_NAME?"; then
  az keyvault secret set --vault-name "$VAULT_NAME" --name "$SECRET_NAME" --value "$PRIVATE_KEY" >/dev/null
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$SECRET_NAME" "$VAULT_NAME"
else
  warn "The settings of the next stages need this secret. The wizard stops, and the new key pair is lost."
  exit 1
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Let the backend read the secret"
VAULT_ID=$(az keyvault show --name "$VAULT_NAME" --query id -o tsv)
SECRET_SCOPE="$VAULT_ID/secrets/$SECRET_NAME"
if [[ "$(az keyvault show --name "$VAULT_NAME" --query properties.enableRbacAuthorization -o tsv)" == "true" ]]; then
  ROLES=$(az role assignment list --assignee "$IDENTITY_PRINCIPAL_ID" --scope "$SECRET_SCOPE" --include-inherited \
    --query "[?roleDefinitionName=='Key Vault Secrets User' || roleDefinitionName=='Key Vault Secrets Officer' || roleDefinitionName=='Key Vault Administrator'].roleDefinitionName" -o tsv)
  if [[ -n "$ROLES" ]]; then
    note "The backend identity can already read the secret ($(printf '%s' "$ROLES" | head -n1))."
  elif confirm "Give the backend identity the role \"Key Vault Secrets User\" on $SECRET_NAME?"; then
    az role assignment create --assignee-object-id "$IDENTITY_PRINCIPAL_ID" --assignee-principal-type ServicePrincipal \
      --role "Key Vault Secrets User" --scope "$SECRET_SCOPE" >/dev/null
    printf '  %s✓ assigned%s Key Vault Secrets User on %s\n' "$GREEN" "$RESET" "$SECRET_NAME"
  else
    SKIPPED+=("Assign Key Vault Secrets User on $SECRET_SCOPE to $IDENTITY_PRINCIPAL_ID")
  fi
else
  SECRET_PERMISSIONS=$(az keyvault show --name "$VAULT_NAME" \
    --query "properties.accessPolicies[?objectId=='$IDENTITY_PRINCIPAL_ID'].permissions.secrets[]" -o tsv)
  if printf '%s\n' "$SECRET_PERMISSIONS" | grep -qiE '^(get|all)$'; then
    note "The access policy of $VAULT_NAME already lets the backend identity get a secret."
  elif confirm "Give the backend identity the secret permission get in the access policy of $VAULT_NAME?"; then
    az keyvault set-policy --name "$VAULT_NAME" --object-id "$IDENTITY_PRINCIPAL_ID" --secret-permissions get >/dev/null
    printf '  %s✓ set%s the secret permission get\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("Give $IDENTITY_PRINCIPAL_ID the secret permission get on $VAULT_NAME")
  fi
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Give the settings to the backend"
say "Push services use the subject to reach the sender, so it is a mailto: address or an https URL."
[[ -n "$CURRENT_SUBJECT" ]] && note "Current subject: $CURRENT_SUBJECT (Enter keeps it)"
ask WEB_PUSH_SUBJECT "Subject (for example mailto:you@example.com):" || true
WEB_PUSH_SUBJECT="${WEB_PUSH_SUBJECT:-$CURRENT_SUBJECT}"
[[ -n "$WEB_PUSH_SUBJECT" ]] || { warn "The subject is empty. The wizard stops before the settings."; exit 1; }
[[ "$WEB_PUSH_SUBJECT" == mailto:* || "$WEB_PUSH_SUBJECT" == https://* ]] || WEB_PUSH_SUBJECT="mailto:$WEB_PUSH_SUBJECT"
note "WebPush__Subject=$WEB_PUSH_SUBJECT"
note "WebPush__PublicKey=$PUBLIC_KEY"
note "WebPush__PrivateKeyFromKeyVault=$SECRET_NAME"
if confirm "Write the three settings to $FUNCTION_APP? The Function App restarts."; then
  az functionapp config appsettings set -n "$FUNCTION_APP" -g "$APP_RG" --settings \
    "WebPush__Subject=$WEB_PUSH_SUBJECT" \
    "WebPush__PublicKey=$PUBLIC_KEY" \
    "WebPush__PrivateKeyFromKeyVault=$SECRET_NAME" >/dev/null
  printf '  %s✓ wrote%s the settings to %s\n' "$GREEN" "$RESET" "$FUNCTION_APP"
else
  SKIPPED+=("Write WebPush__Subject, WebPush__PublicKey=$PUBLIC_KEY, and WebPush__PrivateKeyFromKeyVault=$SECRET_NAME to $FUNCTION_APP")
fi
pause

else
  # Stages 3 to 5 do not run, so the last stage still shows 6 of 6.
  _STAGE_INDEX=5
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Give the public key to the admin"
say "The admin sends the public key to the browser when the author turns on notifications."
CONFIG_KEY=$(python3 -c 'import json, sys; print(json.load(open(sys.argv[1]))["release"].get("vapidPublicKey", ""))' "$ADMIN_CONFIG")
if [[ "$CONFIG_KEY" == "$PUBLIC_KEY" ]]; then
  note "The release section of $ADMIN_CONFIG already has this key."
elif confirm "Write the public key to vapidPublicKey in the release section of $ADMIN_CONFIG?"; then
  python3 - "$ADMIN_CONFIG" "$PUBLIC_KEY" <<'PY'
import json, sys
path, key = sys.argv[1], sys.argv[2]
with open(path) as file:
    config = json.load(file)
config["release"]["vapidPublicKey"] = key
with open(path, "w") as file:
    file.write(json.dumps(config, indent=2) + "\n")
PY
  printf '  %s✓ wrote%s vapidPublicKey → %s\n' "$GREEN" "$RESET" "$ADMIN_CONFIG"
  SKIPPED+=("Commit $ADMIN_CONFIG and merge it, so that the deployed admin gets the key")
else
  SKIPPED+=("Write $PUBLIC_KEY to vapidPublicKey in the release section of $ADMIN_CONFIG")
fi
pause

finish
}

run_wizard "$@"; exit
